//! Scrollable, non-activating reset announcement card owned by the bar.
use super::*;
use std::time::{Duration,Instant};
const W:f32=560.;const H:f32=470.;const LIST_TOP:f32=155.;const LIST_H:f32=132.;const ROW:f32=32.;
fn scroll_at(current:f32,delta:i16,max:f32)->f32{(current-delta as f32/120.*ROW).clamp(0.,max.max(0.))}
fn local_date(t:f64)->String{chrono::DateTime::from_timestamp(t as i64,0).filter(|_|t>0.).map(|v|v.with_timezone(&chrono::Local).format("%m-%d %H:%M").to_string()).unwrap_or_else(||"—".into())}
fn age(t:f64,now:f64,zh:bool)->String{let delta=(now-t).max(0.) as u64;if delta<60{if zh{"刚刚".into()}else{"just now".into()}}else if delta<3600{if zh{format!("{} 分钟前",delta/60)}else{format!("{}m ago",delta/60)}}else if delta<86400{if zh{format!("{} 小时前",delta/3600)}else{format!("{}h ago",delta/3600)}}else if zh{format!("{} 天前",delta/86400)}else{format!("{}d ago",delta/86400)}}
fn cut(s:&str,n:usize)->String{let mut chars=s.chars();let mut out:String=chars.by_ref().take(n).collect();if chars.next().is_some(){out.push('…');}out}
fn event_title(event:&crate::reset_notice::DynamicEvent,zh:bool)->&'static str{match(event.kind.as_str(),event.observed,zh){("banked",true,true)=>"已观测 Banked 重置",("banked",true,false)=>"Banked reset observed",("banked",false,true)=>"Banked 相关公告",("banked",false,false)=>"Banked announcement",("regular",true,true)=>"已观测额度重置",("regular",true,false)=>"Quota reset observed",("regular",false,true)=>"额度相关公告",("regular",false,false)=>"Quota announcement",(_,_,true)=>"其他动态",_=>"Other update"}}
fn events(view:&crate::reset_notice::View)->Vec<crate::reset_notice::DynamicEvent>{
 if !view.events.is_empty(){return view.events.clone()}
 view.history.iter().map(|n|{let p=n.posts.first();crate::reset_notice::DynamicEvent{id:n.id.clone(),kind:"regular".into(),at:if n.announced_at>0.{n.announced_at}else{n.at},author:p.map(|p|p.author.clone()).unwrap_or_default(),text:p.map(|p|p.original.clone()).unwrap_or_else(||n.summary.clone()),translation:p.map(|p|p.translation.clone()).unwrap_or_default(),observed:p.is_some_and(|p|p.observed)}}).collect()
}
pub(super) struct ResetHover{pub window:HWND,visible:bool,since:Instant,candidate:bool,last_inside:Instant,scroll:f32,max:f32,height:f32,drag:Option<f32>,signature:String}
impl ResetHover{
 pub unsafe fn new(owner:HWND)->Result<Self>{let window=CreateWindowExW(WS_EX_TOOLWINDOW|WS_EX_NOACTIVATE,CLASS,w!("Codex Reset Hover"),WS_POPUP,0,0,W as i32,H as i32,owner,None,GetModuleHandleW(None)?,None)?;Ok(Self{window,visible:false,since:Instant::now(),candidate:false,last_inside:Instant::now(),scroll:0.,max:0.,height:H,drag:None,signature:String::new()})}
 pub unsafe fn contains_cursor(&self)->bool{if !self.visible{return false}let mut p=POINT::default();let mut r=RECT::default();GetCursorPos(&mut p).is_ok()&&GetWindowRect(self.window,&mut r).is_ok()&&p.x>=r.left&&p.x<r.right&&p.y>=r.top&&p.y<r.bottom}
 unsafe fn hide(&mut self){if self.drag.take().is_some(){let _=ReleaseCapture();}if self.visible{let _=ShowWindow(self.window,SW_HIDE);}self.visible=false;self.candidate=false;self.scroll=0.;self.max=0.;}
 unsafe fn show(&mut self,owner:HWND,r:D2D_RECT_F){let scale=GetDpiForWindow(owner).max(96) as f32/96.;let mut origin=POINT::default();if !ClientToScreen(owner,&mut origin).as_bool(){return}let mut info=MONITORINFO{cbSize:size_of::<MONITORINFO>() as u32,..Default::default()};let _=GetMonitorInfoW(MonitorFromWindow(owner,MONITOR_DEFAULTTONEAREST),&mut info);let work=info.rcWork;let w=(W*scale) as i32;let desired=(H*scale) as i32;let below=origin.y+(r.bottom*scale) as i32+5;let above=origin.y+(r.top*scale) as i32-5;let available_b=(work.bottom-below).max(0);let available_a=(above-work.top).max(0);let height=desired.min(available_b.max(available_a));if height<(390.*scale) as i32{return}let y=if available_b>=height{below}else{above-height};let x=(origin.x+(r.right*scale) as i32-w).clamp(work.left,(work.right-w).max(work.left));self.height=height as f32/scale;App::round_window(self.window,w,height,(12.*scale) as i32);if SetWindowPos(self.window,HWND_TOP,x,y,w,height,SWP_NOACTIVATE|SWP_SHOWWINDOW).is_ok(){self.visible=true;self.scroll=0.;self.last_inside=Instant::now();let _=InvalidateRect(self.window,None,false);}}
}
impl App{
 pub(super) unsafe fn update_reset_hover(&mut self){if self.hidden||self.host_hidden||!self.settings.reset_notice.enabled{self.reset_hover.hide();return}let now=Instant::now();if self.reset_hover.visible{let live=self.snapshot();let v=&live.reset_notice;let sig=format!("{}|{}|{}|{}|{}",v.checked_at,v.attempted_at,v.events.len(),v.history.len(),v.error);if sig!=self.reset_hover.signature{self.reset_hover.signature=sig;let _=InvalidateRect(self.reset_hover.window,None,false);}}if self.reset_hover.contains_cursor(){self.reset_hover.last_inside=now;return}let target=matches!(self.hover,Some(Hit::ResetNotice(_)));if target{self.reset_hover.last_inside=now;if !self.reset_hover.candidate{self.reset_hover.candidate=true;self.reset_hover.since=now;}if !self.reset_hover.visible&&now.duration_since(self.reset_hover.since)>=Duration::from_millis(450){if let Some(r)=self.hits.iter().find(|a|matches!(a.hit,Hit::ResetNotice(_))).map(|a|a.r){self.reset_hover.show(self.bar,r);}}}else if self.reset_hover.visible&&now.duration_since(self.reset_hover.last_inside)<Duration::from_millis(450){}else{self.reset_hover.hide();}}
 pub(super) unsafe fn draw_reset_hover(&self,scroll:f32)->f32{
  let p=&self.painter;let zh=crate::locale::chinese();let live=self.snapshot();let view=&live.reset_notice;let now=crate::now();let height=self.reset_hover.height;let list_h=(height-338.).clamp(30.,LIST_H);let bottom=LIST_TOP+list_h;
  p.fill(rect(0.,0.,W,height),0x233238,10.);p.border(rect(0.5,0.5,W-1.,height-1.),0x526d75,10.);
  p.notice_bell(15.,12.,0xc5d3d6);p.label(if zh{"额度重置动态"}else{"Reset announcements"},rect(39.,8.,280.,31.),13.,TEXT,false);
  p.fill(rect(W-165.,11.,149.,25.),0x2a4350,12.);p.circle(W-154.,23.,3.,NEW_RESULT);p.label(if matches!(view.source,crate::reset_notice::Source::Divin){"AI Sentinel"}else{"Codex Resets"},rect(W-145.,11.,130.,25.),10.,0x9ccce0,false);p.line(16.,47.,W-16.,47.,0x40535a,1.);
  p.fill(rect(16.,58.,W-32.,67.),0x1d2a30,6.);p.circle(30.,80.,3.,MUTED);p.label(if zh{"下一次官方重置"}else{"Next announced reset"},rect(42.,62.,260.,21.),10.,MUTED,false);
  let stale=view.checked_at>0.&&now-view.checked_at>6.*3600.;let value=view.active(now).filter(|n|n.at>now).map(|n|n.short(now,zh)).unwrap_or_else(||if stale{if zh{"数据已过期"}else{"Data is outdated"}}else if zh{"暂无明确时间"}else{"No explicit time"}.into());p.label(&value,rect(42.,82.,W-85.,31.),14.,TEXT,false);
  p.circle(24.,142.,3.,GREEN);p.label(if zh{"最近动态"}else{"Recent activity"},rect(35.,130.,220.,24.),11.,TEXT,false);
  let items=events(view);let max=(items.len() as f32*ROW-list_h).max(0.);let scroll=scroll.clamp(0.,max);
  p.target.PushAxisAlignedClip(&rect(16.,LIST_TOP,W-32.,list_h),D2D1_ANTIALIAS_MODE_ALIASED);
  if items.is_empty(){p.label(if zh{"暂无可显示的动态"}else{"No recent activity"},rect(28.,LIST_TOP,W-60.,30.),11.,MUTED,false);}
  for(i,e)in items.iter().enumerate(){let y=LIST_TOP+i as f32*ROW-scroll;if y+ROW<LIST_TOP||y>bottom{continue}p.fill(rect(16.,y,W-32.,ROW-3.),0x1c2b30,5.);let color=if e.observed{GREEN}else{NEW_RESULT};p.circle(29.,y+15.,3.,color);p.label(event_title(e,zh),rect(40.,y,150.,29.),11.,color,false);let summary=if !e.translation.is_empty(){&e.translation}else{&e.text};p.label(&cut(summary,24),rect(192.,y,145.,29.),10.,TEXT,false);let time=format!("{} · {}",age(e.at,now,zh),local_date(e.at));p.right_label(&time,rect(W-210.,y,180.,29.),10.,MUTED);}
  p.target.PopAxisAlignedClip();if max>0.{let thumb=(list_h*list_h/(list_h+max)).max(20.);let yy=LIST_TOP+(list_h-thumb)*scroll/max;p.fill(rect(W-12.,LIST_TOP,3.,list_h),0x40535a,2.);p.fill(rect(W-12.,yy,3.,thumb),0x8aa5ae,2.);}
  let section=bottom+9.;p.circle(24.,section+11.,3.,NEW_RESULT);p.label(if zh{"最新公告"}else{"Latest announcement"},rect(35.,section,300.,22.),11.,TEXT,false);
  let event=items.iter().filter(|e|!e.observed).max_by(|a,b|a.at.total_cmp(&b.at));
  let notice=view.current.iter().chain(view.history.iter()).filter_map(|n|n.posts.iter().find(|p|!p.observed).map(|p|(n.announced_at,p))).max_by(|a,b|a.0.total_cmp(&b.0));
  let (author,original,translation)=if let Some(e)=event.filter(|e|notice.is_none_or(|(t,_)|e.at>=t)){(e.author.as_str(),e.text.as_str(),e.translation.as_str())}else if let Some((_,p))=notice{(p.author.as_str(),p.original.as_str(),p.translation.as_str())}else{("—","","")};
  p.fill(rect(16.,section+26.,W-32.,92.),0x1c2b30,5.);p.label(author,rect(26.,section+29.,W-52.,20.),10.,0x9ccce0,false);let original=if original.is_empty(){if zh{"暂无公告"}else{"No announcement"}.into()}else{format!("{} {}",if zh{"原文"}else{"Original"},cut(original,200))};p.wrapped_label(&original,rect(26.,section+51.,W-52.,30.),10.,TEXT);if !translation.is_empty(){p.wrapped_label(&format!("{} {}",if zh{"译文"}else{"Translation"},cut(translation,170)),rect(26.,section+81.,W-52.,30.),10.,MUTED);}
  p.line(16.,height-35.,W-16.,height-35.,0x40535a,1.);let status=view.check_status(zh);p.label(&cut(&status,74),rect(18.,height-31.,W-120.,26.),10.,MUTED,false);p.label(if zh{"打开来源 ↗"}else{"Open source ↗"},rect(W-100.,height-31.,88.,26.),10.,NEW_RESULT,false);max
 }
 pub(super) unsafe fn reset_hover_message(&mut self,hwnd:HWND,msg:u32,w:WPARAM,l:LPARAM)->Option<LRESULT>{let scale=GetDpiForWindow(hwnd).max(96) as f32/96.;let x=(l.0 as i16) as f32/scale;let y=((l.0>>16) as i16) as f32/scale;let list_h=(self.reset_hover.height-338.).clamp(30.,LIST_H);match msg{
  WM_MOUSEACTIVATE=>Some(LRESULT(MA_NOACTIVATE as isize)),WM_ERASEBKGND=>Some(LRESULT(1)),
  WM_PAINT=>{let mut ps=PAINTSTRUCT::default();let dc=BeginPaint(hwnd,&mut ps);let mut r=RECT::default();let _=GetClientRect(hwnd,&mut r);if self.painter.target.BindDC(dc,&r).is_ok(){self.painter.target.SetDpi(96.*scale,96.*scale);self.painter.target.BeginDraw();let max=self.draw_reset_hover(self.reset_hover.scroll);self.reset_hover.max=max;self.reset_hover.scroll=self.reset_hover.scroll.clamp(0.,max);let _=self.painter.target.EndDraw(None,None);}let _=EndPaint(hwnd,&ps);Some(LRESULT(0))},
  WM_MOUSEWHEEL=>{self.reset_hover.scroll=scroll_at(self.reset_hover.scroll,(w.0>>16) as i16,self.reset_hover.max);self.reset_hover.last_inside=Instant::now();let _=InvalidateRect(hwnd,None,false);Some(LRESULT(0))},
  WM_MOUSEMOVE=>{self.reset_hover.last_inside=Instant::now();if let Some(grab)=self.reset_hover.drag{let max=self.reset_hover.max;let thumb=(list_h*list_h/(list_h+max)).max(20.);if max>0.{self.reset_hover.scroll=((y-LIST_TOP-grab)/(list_h-thumb)).clamp(0.,1.)*max;let _=InvalidateRect(hwnd,None,false);}}Some(LRESULT(0))},
  WM_LBUTTONDOWN if x>=W-23.&&y>=LIST_TOP&&y<LIST_TOP+list_h&&self.reset_hover.max>0.=>{let max=self.reset_hover.max;let thumb=(list_h*list_h/(list_h+max)).max(20.);let top=LIST_TOP+(list_h-thumb)*self.reset_hover.scroll/max;self.reset_hover.drag=Some(if y>=top&&y<=top+thumb{y-top}else{thumb/2.});let _=SetCapture(hwnd);Some(LRESULT(0))},
  WM_LBUTTONUP=>{if self.reset_hover.drag.take().is_some(){let _=ReleaseCapture();}else if x>=W-110.&&y>=self.reset_hover.height-35.{let source=self.settings.reset_notice.source;let _=ShellExecuteW(self.bar,w!("open"),PCWSTR(wide(source.url()).as_ptr()),PCWSTR::null(),PCWSTR::null(),SW_SHOWNORMAL);}Some(LRESULT(0))},_=>None}}
}
#[cfg(test)]mod tests{use super::*;#[test]fn list_scroll_and_event_types(){assert_eq!(scroll_at(0.,-120,200.),32.);assert_eq!(scroll_at(190.,-120,200.),200.);assert_eq!(scroll_at(10.,120,200.),0.);let mut e=crate::reset_notice::DynamicEvent{kind:"banked".into(),..Default::default()};assert_eq!(event_title(&e,true),"Banked 相关公告");e.observed=true;assert_eq!(event_title(&e,true),"已观测 Banked 重置");}}
